import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/usuario.dart';
import '../services/usuario_service.dart';
import '../services/dashboard_service.dart';
import '../widgets/async_ui.dart';
class AdminUsuariosPage extends StatefulWidget {const AdminUsuariosPage({super.key});@override State<AdminUsuariosPage> createState()=>_AdminUsuariosPageState();}
class _AdminUsuariosPageState extends State<AdminUsuariosPage>{final service=UsuarioService();late final Stream<QuerySnapshot<Map<String,dynamic>>> stream;String busca='',tipo='Todos',situacao='Todos';
 @override void initState(){super.initState();stream=service.usuarios.snapshots();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Gerenciar usuários')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:stream,builder:(context,s){if(s.hasError)return erro(s.error);if(!s.hasData)return espera();final lista=s.data!.docs.map((d)=>Usuario(d.id,d.data())).where((u)=>('${u.nome} ${u.email} ${u.cidade}'.toLowerCase().contains(busca.toLowerCase()))&&(tipo=='Todos'||u.tipo==tipo)&&(situacao=='Todos'||u.ativo==(situacao=='Ativos'))).toList();return Column(children:[TextField(decoration:const InputDecoration(labelText:'Nome, e-mail ou cidade'),onChanged:(v)=>setState(()=>busca=v)),Wrap(spacing:12,children:[DropdownButton<String>(value:tipo,items:['Todos','admin','usuario'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>tipo=v!)),DropdownButton<String>(value:situacao,items:['Todos','Ativos','Bloqueados'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>situacao=v!))]),Expanded(child:ListView.builder(itemCount:lista.length,itemBuilder:(context,i){final u=lista[i];return Card(child:ListTile(title:Text(u.nome),subtitle:Text('${u.email} • ${u.cidade} • ${u.tipo} • ${u.ativo?'Ativo':'Bloqueado'}'),trailing:u.tipo=='usuario'?IconButton(icon:Icon(u.ativo?Icons.lock:Icons.lock_open),onPressed:()async{if(await confirmar(context,'Alterar situação de ${u.nome}?')&&context.mounted)await executar(context,()=>service.situacao(u.uid,!u.ativo));}):null));}))]);}));
}
class DashboardPage extends StatefulWidget{const DashboardPage({super.key});@override State<DashboardPage> createState()=>_DashboardPageState();}
class _DashboardPageState extends State<DashboardPage>{late Future<Map<String,int>> dados;@override void initState(){super.initState();dados=DashboardService().carregar();}void atualizar()=>setState(()=>dados=DashboardService().carregar());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Dashboard'),actions:[IconButton(onPressed:atualizar,icon:const Icon(Icons.refresh))]),body:FutureBuilder<Map<String,int>>(future:dados,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return espera();if(s.hasError)return erro(s.error);final d=s.data!;final total=d['Animais']??0;final taxa=total==0?0:(d['Animais: adotado']??0)/total*100;return ListView(padding:const EdgeInsets.all(12),children:[Text('Taxa de adoção: ${taxa.toStringAsFixed(1)}%',style:Theme.of(context).textTheme.titleLarge),Text('Usuários ativos: ${(d['Usuários']??0)-(d['Bloqueados']??0)}'),for(final e in d.entries)Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.key),Text('${e.value}',style:Theme.of(context).textTheme.headlineSmall),if(['Cachorro','Gato','Outro'].contains(e.key))LinearProgressIndicator(value:total==0?0:(e.value/total).clamp(0,1).toDouble())]))) ]);}));
}
